/// Resolves compressed preview variants generated by tool/generate_image_previews.py.
abstract final class PreviewAssets {
  /// Maps an original portfolio/profile asset path to its preview JPEG when applicable.
  static String resolve(String assetPath) {
    if (assetPath.contains('/preview/')) return assetPath;

    if (assetPath == 'images/profile/sajjad-ali.png') {
      return 'images/profile/preview/sajjad-ali.jpg';
    }

    const marker = 'images/portfolio/';
    if (!assetPath.startsWith(marker)) return assetPath;

    final rest = assetPath.substring(marker.length);
    final slash = rest.indexOf('/');
    if (slash < 0) return assetPath;

    final project = rest.substring(0, slash);
    var file = rest.substring(slash + 1);
    if (file.startsWith('full-hd/')) {
      file = file.substring('full-hd/'.length);
    }
    if (file.startsWith('preview/')) return assetPath;

    final stem = file.contains('.')
        ? file.substring(0, file.lastIndexOf('.'))
        : file;
    return '$marker$project/preview/$stem.jpg';
  }

  static List<String> resolveAll(Iterable<String> assets) {
    return assets.map(resolve).toList(growable: false);
  }
}
